import 'package:flutter/material.dart';import 'package:modulos/core/theme/app_colors.dart';import 'package:modulos/core/widgets/responsive_layout.dart';import '../controllers/inventario_controller.dart';import '../widgets/inventario_form.dart';import '../widgets/inventario_table.dart';import '../widgets/inventario_actions.dart';class InventarioScreen extends StatefulWidget {  final int selectedNav;  final ValueChanged<int> onNavSelect;  const InventarioScreen({super.key, required this.selectedNav, required this.onNavSelect});  @override  State<InventarioScreen> createState() => _InventarioScreenState();}class _InventarioScreenState extends State<InventarioScreen> {  final _controller = InventarioController();  @override  void initState() {    super.initState();    _controller.addListener(() => setState(() {}));    _controller.cargarDatos();  }  @override  void dispose() {    _controller.dispose();    super.dispose();  }  void _abrirFormularioMovimiento() {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => InventarioMovimientoForm(        onSubmit: ({required String productoId, required String tipo, required int cantidad, String? descripcion, required String usuarioId}) async {          await _controller.registrarMovimiento(            productoId: productoId,            tipo: tipo,            cantidad: cantidad,            descripcion: descripcion,            usuarioId: usuarioId,          );          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              const SnackBar(content: Text('Movimiento registrado')),            );          }        },      ),    );  }  void _abrirFormularioEdicion(dynamic existente) {    showModalBottomSheet(      context: context,      isScrollControlled: true,      backgroundColor: AppColors.cardBg,      shape: const RoundedRectangleBorder(        borderRadius: BorderRadius.vertical(top: Radius.circular(20)),      ),      builder: (_) => InventarioEditForm(        existente: existente,        onSubmit: (item) async {          await _controller.actualizarInventario(item);          if (mounted) {            ScaffoldMessenger.of(context).showSnackBar(              const SnackBar(content: Text('Inventario actualizado')),            );          }        },      ),    );  }  @override  Widget build(BuildContext context) {    return ResponsiveLayout(      selectedNav: widget.selectedNav,      onNavSelect: widget.onNavSelect,      title: 'Inventario',      contentBuilder: (context, constraints) => _buildContent(),    );  }  Widget _buildHeader() {    final count = _controller.filtroVista == 'stock'        ? _controller.inventarioItems.length        : _controller.filtroVista == 'bajo'            ? _controller.stockBajoItems.length            : _controller.movimientos.length;    return PageHeader(      title: 'Gestión de Inventario',      count: count,      buttonLabel: 'Registrar Movimiento',      onButtonPressed: _abrirFormularioMovimiento,    );  }  Widget _buildFiltros() {    return Wrap(      spacing: 8,      runSpacing: 8,      children: [        _buildFiltroChip('Stock General', 'stock'),        _buildFiltroChip('Stock Bajo', 'bajo'),        _buildFiltroChip('Movimientos', 'movimientos'),      ],    );  }  Widget _buildFiltroChip(String label, String valor) {    final isSelected = _controller.filtroVista == valor;    return FilterChip(      label: Text(label),      selected: isSelected,      onSelected: (_) {        _controller.setFiltroVista(valor);        _controller.cargarDatos();      },      selectedColor: AppColors.brandGreen,      checkmarkColor: Colors.white,      labelStyle: TextStyle(        color: isSelected ? Colors.white : AppColors.textSecondary,        fontWeight: isSelected ? FontWeight.w600 : FontWeight.normal,      ),    );  }  Widget _buildContent() {    if (_controller.isLoading) {      return const Center(        child: Padding(          padding: EdgeInsets.all(40),          child: CircularProgressIndicator(),        ),      );    }    if (_controller.error != null) {      return Center(        child: Column(          mainAxisAlignment: MainAxisAlignment.center,          children: [            const Icon(Icons.error_outline, size: 48, color: AppColors.negativeRed),            const SizedBox(height: 16),            Text('Error: ${_controller.error}', style: const TextStyle(color: AppColors.textPrimary)),            const SizedBox(height: 16),            ElevatedButton(              onPressed: _controller.cargarDatos,              child: const Text('Reintentar'),              ),          ],        ),      );    }    return Column(      crossAxisAlignment: CrossAxisAlignment.start,      children: [        _buildHeader(),        const SizedBox(height: 16),        _buildFiltros(),        const SizedBox(height: 16),        InventarioTable(            tipo: _controller.filtroVista,            inventarioItems: _controller.inventarioItems,            stockBajoItems: _controller.stockBajoItems,            movimientos: _controller.movimientos,            onEdit: (item) => _abrirFormularioEdicion(item),            onDelete: (item) => InventarioActions.confirmarEliminar(context, item, () async {              try {                await _controller.eliminarInventario(item.id);                if (mounted) {                  ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content: Text('Inventario eliminado')));                }              } catch (e) {                if (mounted) {                  ScaffoldMessenger.of(context).showSnackBar(                    SnackBar(content: Text('Error: $e'), backgroundColor: AppColors.negativeRed),                  );                }              }            }),          ),      ],    );  }}